package controlplane

const productTemplates = `
{{define "style"}}<style>
:root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#172033;background:#f6f8fc}*{box-sizing:border-box}body{margin:0}header{background:#fff;border-bottom:1px solid #dfe5f0;padding:18px 5vw;display:flex;justify-content:space-between;align-items:center;gap:18px}header strong{font-size:18px}header nav{display:flex;gap:14px;align-items:center;margin-left:auto}header a{color:#245bd6;text-decoration:none;font-weight:650}main{max-width:1100px;margin:36px auto;padding:0 20px}h1{font-size:32px;margin:0 0 10px}h2{font-size:20px;margin:0 0 12px}h3{font-size:17px;margin:0 0 8px}p{line-height:1.55;color:#53617a}.button,button{border:1px solid #b8c4dc;background:#fff;color:#172033;border-radius:8px;padding:11px 15px;font:inherit;cursor:pointer;text-decoration:none;display:inline-block}.primary,button.primary{background:#245bd6;border-color:#245bd6;color:#fff;font-weight:650}.button.attention,button.attention{background:#fff3df;border-color:#e5b46c;color:#7b4c12;font-weight:650}.hero{background:linear-gradient(135deg,#eef4ff,#fff);border:1px solid #d9e3f7;border-radius:18px;padding:42px;margin:20px 0}.card{background:#fff;border:1px solid #dfe5f0;border-radius:14px;padding:22px;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}.muted{color:#6b7890;font-size:14px}.badge{display:inline-flex;align-items:center;border-radius:999px;padding:5px 10px;background:#e8f5ec;color:#216b38;font-size:13px;font-weight:650}.badge.attention{background:#fff3df;color:#8b5b13}.badge.disconnected{background:#eef0f5;color:#5d6880}.error{background:#fff0f0;border:1px solid #efb6b6;color:#8b1e1e;padding:12px;border-radius:8px;margin:12px 0}.message{background:#e8f5ec;border:1px solid #b9dfc5;color:#216b38;padding:12px;border-radius:8px;margin:12px 0}.empty{text-align:center;padding:35px 15px}.stack{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.search{display:flex;gap:10px;margin:18px 0}.search input{flex:1;border:1px solid #b8c4dc;border-radius:8px;padding:11px 13px;font:inherit}.service{margin:18px 0}.service-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.service-actions{display:flex;gap:8px;flex-wrap:wrap}.service-actions button{padding:7px 10px;font-size:13px}.assets{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:14px}.asset{border:1px solid #e1e7f1;border-radius:12px;padding:15px;display:flex;gap:11px;align-items:flex-start}.asset input{margin-top:4px;width:18px;height:18px;flex:none}.asset strong{display:block}.asset small{color:#6b7890;display:block;margin-top:3px}.asset-id{color:#8a96a8;font-size:12px;word-break:break-all}.saving{margin-top:22px}.reconnect{background:#fff8e8;border:1px solid #e5c58b;border-radius:12px;padding:18px;margin:18px 0}.reconnect h2{margin-bottom:5px}@media(max-width:600px){header{padding:15px 20px;align-items:flex-start;flex-wrap:wrap}header nav{margin-left:0;width:100%}main{margin:22px auto}.hero{padding:25px}h1{font-size:27px}.stack .button,.stack button{flex:1;text-align:center}.service-head{display:block}.service-actions{margin-top:12px}.assets{grid-template-columns:1fr}}
</style>{{end}}
{{define "signin"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in · gog-marketing</title>{{template "style" .}}</head><body><header><strong>gog-marketing</strong></header><main><div class="hero"><h1>Welcome to gog-marketing</h1><p>Connect your Google marketing data and make it ready for your marketing work.</p>{{if .Error}}<div class="error">{{.Error}}</div>{{end}}<a class="button primary" href="/auth/google/start">Continue with Google</a><p class="muted">This version supports the configured workspace owner. Use that Google account; we take care of the connection details.</p></div></main></body></html>{{end}}
{{define "home"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Home · gog-marketing</title>{{template "style" .}}</head><body><header><strong>gog-marketing</strong><span class="muted">{{.DisplayName}}</span><nav><a href="/">Home</a><form class="inline" method="post" action="/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button>Sign out</button></form></nav></header><main><div class="hero"><h1>Your Google data</h1><p>Choose what gog-marketing can use, then start working with your marketing data.</p><div class="stack"><form method="post" action="/connect/google"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="primary">Connect Google</button></form>{{if .Connection.ID}}<a class="button" href="/assets/{{.Connection.ID}}">Manage access</a>{{end}}</div></div>{{if .Error}}<div class="error">{{.Error}}</div>{{end}}{{if .Message}}<div class="message">{{.Message}}</div>{{end}}{{if .NeedsReconnect}}<div class="reconnect"><h2>Google needs you to reconnect this account</h2><p>Your workspace can keep the selected assets, but Google needs a new sign-in before it can refresh access.</p><form method="post" action="/assets/{{.Connection.ID}}/reconnect"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="attention">Reconnect Google</button></form></div>{{end}}<div class="grid"><div class="card"><h2>Connection</h2>{{if .Connection.ID}}<p><span class="badge{{if eq .State "needs_attention"}} attention{{else if eq .State "disconnected"}} disconnected{{end}}">{{.StateLabel}}</span></p><p>{{if .Connection.GoogleEmail}}{{.Connection.GoogleEmail}}{{else}}Connect Google to get started.{{end}}</p>{{else}}<p>Connect Google to get started.</p>{{end}}</div><div class="card"><h2>Available assets</h2><p><strong>{{.AssetCount}}</strong> Google assets are ready to use across <strong>{{.ServiceCount}}</strong> services.</p><p class="muted">Google Analytics, Google Ads, Tag Manager, Search Console and BigQuery appear here after discovery.</p></div><div class="card"><h2>Next step</h2><p>Review the names of the properties, accounts and sites you want to expose.</p>{{if .Connection.ID}}<a class="button" href="/assets/{{.Connection.ID}}">Choose assets</a>{{else}}<form method="post" action="/connect/google"><input type="hidden" name="csrf" value="{{.CSRF}}"><button>Connect Google</button></form>{{end}}</div></div></main></body></html>{{end}}
{{define "assets"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Choose assets · gog-marketing</title>{{template "style" .}}</head><body><header><strong>gog-marketing</strong><nav><a href="/">Home</a><form method="post" action="/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button>Sign out</button></form></nav></header><main><h1>Choose what gog-marketing can access</h1><p>These are the Google marketing assets available to your workspace. Select the ones you want to use.</p>{{if .Error}}<div class="error">{{.Error}}</div>{{end}}{{if .NeedsReconnect}}<div class="reconnect"><h2>Google needs you to reconnect this account</h2><p>Reconnect to refresh Google access and keep working with your selected assets.</p><form method="post" action="/assets/{{.Connection.ID}}/reconnect"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="attention">Reconnect Google</button></form></div>{{else if .CanRetry}}<div class="stack"><form class="inline" method="post" action="/assets/{{.Connection.ID}}/discover"><input type="hidden" name="csrf" value="{{.CSRF}}"><button>Try again</button></form></div>{{end}}{{if .ServiceStatuses}}<section class="card"><h2>Service discovery</h2>{{range .ServiceStatuses}}<p>{{.ServiceName}}: {{.Detail}}</p>{{end}}</section>{{end}}<form method="get" action="/assets/{{.Connection.ID}}"><div class="search"><input type="search" name="q" value="{{.Query}}" placeholder="Search assets"><button type="submit">Search</button></div></form>{{if .HasAssets}}<form method="post" action="/assets/{{.Connection.ID}}/save"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="q" value="{{.Query}}">{{range .Groups}}<section class="service"><div class="service-head"><div><h2>{{.ServiceName}}</h2><p class="muted">{{.Count}} assets · {{.EnabledCount}} selected · {{.StatusLabel}}</p>{{if .StatusDetail}}<small class="muted">{{.StatusDetail}}</small>{{end}}</div><div class="service-actions"><button name="select_all" value="{{.ServiceName}}">Select all in service</button><button name="select_none" value="{{.ServiceName}}">Select none in service</button></div></div><div class="assets">{{range .Assets}}<div class="asset"><input id="asset-{{.ResourceID}}" name="resource" value="{{.ResourceID}}" type="checkbox"{{if .Enabled}} checked{{end}}><label for="asset-{{.ResourceID}}"><strong>{{.Name}}</strong><small>{{.Kind}}{{if .Parent}} · {{.Parent}}{{end}}</small>{{if .ReadURL}}<a href="{{.ReadURL}}">Read property</a>{{end}}<details><summary>Asset details</summary><small class="asset-id">{{.ResourceID}}</small></details></label></div>{{end}}</div></section>{{end}}<div class="saving"><button class="primary" type="submit">Save access</button></div></form>{{else}}<div class="card empty"><h2>No assets found yet</h2><p>Google is connected. Try discovery again in a moment.</p>{{if .CanRetry}}<form method="post" action="/assets/{{.Connection.ID}}/discover"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="primary">Try again</button></form>{{end}}</div>{{end}}</main></body></html>{{end}}

{{define "property"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Google Analytics property · gog-marketing</title>{{template "style" .}}</head><body><header><strong>gog-marketing</strong><nav><a href="/">Home</a><a href="/assets/{{.ConnectionID}}">Manage access</a></nav></header><main>{{if .Error}}<h1>This property could not be read</h1><p>Review its access selection or reconnect Google, then try again.</p><details><summary>Request details</summary><small>{{.Error}}</small></details>{{else}}<h1>{{.Property.DisplayName}}</h1><p>Live Google Analytics property information.</p><div class="card"><h2>Property settings</h2><p>Time zone: {{.Property.TimeZone}}</p><p>Currency: {{.Property.CurrencyCode}}</p></div><details><summary>Agent/API details</summary><small>{{.Property.Name}}</small><p>The authenticated API uses the same asset permission.</p><a href="/api/connections/{{.ConnectionID}}/analytics/property?resource={{.Property.Name}}">Read JSON for an agent</a></details>{{end}}</main></body></html>{{end}}
`
